import lessons from "./interactive.json";
import type { ArticleLevel } from "./catalog";

/**
 * The 13 interactive Intermediate lessons, kept as the supplied HTML files in
 * content/articles/intermediate/ and run unchanged in a sandboxed frame
 * (app/api/articles/lesson/[slug]/route.ts). This module holds metadata only,
 * generated by scripts/import-interactive-articles.mjs.
 */
export type InteractiveLesson = {
  slug: string;
  order: number;
  title: string;
  /** Short topic name from the lesson (UNIT.short), e.g. "Food and cooking". */
  topic: string;
  emoji: string;
  level: ArticleLevel;
  /** The lesson's own level line, e.g. "Intermediate (B1–B2) · English File · Food and cooking". */
  levelLabel: string;
  description: string;
  /** Key words practised in the lesson. */
  wordCount: number;
  /** Words in the reading text, for the "min read" estimate. */
  readingWords: number;
  sourceFile: string;
  sourceSha256: string;
};

export const INTERACTIVE_LESSONS = ([...lessons] as InteractiveLesson[]).sort((a, b) => a.order - b.order);

export function findInteractiveLesson(slug: string) {
  return INTERACTIVE_LESSONS.find(lesson => lesson.slug === slug);
}

/** Same reading speed as the structured lessons (180 words per minute). */
export function interactiveReadingMinutes(lesson: Pick<InteractiveLesson, "readingWords">) {
  return Math.max(1, Math.ceil(lesson.readingWords / 180));
}
